--
-- Table structure for table `print_templates`
--

CREATE TABLE `print_templates` (
  `id_template` int(11) NOT NULL,
  `template_code` varchar(50) NOT NULL,
  `code` varchar(100) DEFAULT NULL,
  `template_name` varchar(100) NOT NULL,
  `template_category` varchar(50) NOT NULL DEFAULT '1',
  `gjs_data` longtext DEFAULT NULL COMMENT 'GrapesJS JSON data for editor state',
  `header_gjs_data` longtext DEFAULT NULL,
  `body_gjs_data` longtext DEFAULT NULL,
  `footer_gjs_data` longtext DEFAULT NULL,
  `header_height` int(11) DEFAULT 100,
  `template_html` longtext DEFAULT NULL COMMENT 'Compiled HTML output',
  `template_css` text DEFAULT NULL COMMENT 'Compiled CSS output',
  `config_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`config_json`)),
  `paper_size` enum('A4','A5','Letter','Thermal-58mm','Thermal-80mm','Custom') DEFAULT 'A4',
  `paper_width` varchar(20) DEFAULT NULL COMMENT 'Custom width e.g. 80mm',
  `paper_height` varchar(20) DEFAULT NULL COMMENT 'Custom height e.g. 297mm',
  `page_orientation` enum('portrait','landscape') DEFAULT 'portrait',
  `margin_top` int(11) DEFAULT 10,
  `margin_right` int(11) DEFAULT 10,
  `margin_bottom` int(11) DEFAULT 10,
  `margin_left` int(11) DEFAULT 10,
  `is_default` tinyint(1) DEFAULT 0,
  `is_active` tinyint(1) DEFAULT 1,
  `version_number` int(11) DEFAULT 1,
  `parent_template_id` int(11) DEFAULT NULL,
  `id_branch` int(11) DEFAULT NULL COMMENT 'NULL = all branches',
  `created_by` int(11) DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

